import {
    type RecordId,
    type Shape,
    type StringShape,
    StringLiteralShape,
    CallExpressionShape,
    Plugin,
} from '@servicenow/sdk-build-core'
import type { InterceptorAnswerType } from '@servicenow/sdk-core/app'
import { NowIdShape } from './now-id-plugin'
import { reverseObject, validateServerScriptField } from './utils'

const INTERCEPTOR_TABLE = 'sys_wizard'
const INTERCEPTOR_ANSWER_TABLE = 'sys_wizard_answer'

// sys_wizard_answer.type <-> InterceptorAnswerType. Platform default code is '1' ('answer').
// Keep in sync with InterceptorAnswerTypeCodes in packages/core/src/app/Interceptor.ts.
// Typed against InterceptorAnswerType so an edit to one that misses the other is a compile error.
const ANSWER_TYPE_TO_CODE: Record<InterceptorAnswerType, string> = {
    answer: '1',
    leadingQuestion: '2',
    multipleChoice: '3',
    yesNo: '4',
    freeformText: '5',
    button: '6',
    externalChoice: '9',
}
const ANSWER_CODE_TO_TYPE = reverseObject(ANSWER_TYPE_TO_CODE)
const DEFAULT_ANSWER_TYPE = 'answer'
// Platform default for sys_wizard_answer.order. Keep in sync with InterceptorAnswer['order']'s
// @default in packages/core/src/app/Interceptor.ts.
const DEFAULT_ORDER = 100

/**
 * Splits a comma-separated platform string into a filtered array, or `undefined` when empty
 * (used so `.def([])` correctly omits the property from generated Fluent code when the source
 * field is blank).
 */
function splitList(raw: string | undefined): string[] | undefined {
    return raw ? raw.split(',').filter(Boolean) : undefined
}

/**
 * Resolves a backPanel/nextPanel/nextQuestion value — a raw sys_id string, a Record<> reference,
 * or a resolved Now.ref() — to its underlying reference shape, without resolving it to a string
 * immediately. This preserves lazy resolution for Now.ref() references so the target record has
 * time to register its explicit ID before the reference value is read. Only used here — this is
 * not a general-purpose framework mechanism, and the automatic Record -> RecordId conversion the
 * XML writer applies at serialization time (see field() in build-core's xml.ts) is too late for
 * this: this resolves the value into the plain reference/string the record's OWN properties need
 * to hold, since other code (e.g. relationship traversal, this file's own tests) reads those
 * properties directly, not just the final serialized XML.
 */
function toReferenceShape(shape: Shape): RecordId | StringShape {
    return shape.ifRecord()?.getId() ?? shape.ifString() ?? new StringLiteralShape({ source: shape, literalText: '' })
}

export const InterceptorPlugin = Plugin.create({
    name: 'InterceptorPlugin',

    records: {
        [INTERCEPTOR_ANSWER_TABLE]: {
            // No toShape: always handled as a descendant of sys_wizard; an orphaned Answer with
            // no reachable parent question falls back to Record().
        },
        [INTERCEPTOR_TABLE]: {
            coalesce: ['name'],

            relationships: {
                [INTERCEPTOR_ANSWER_TABLE]: {
                    via: 'question',
                    descendant: true,
                },
            },

            toShape(record, { descendants, logger }) {
                // `descendants` is already scoped to this record's descendant tree via the
                // declared `via: 'question'` relationship above — no extra filter needed.
                const allAnswers = descendants.query(INTERCEPTOR_ANSWER_TABLE)

                const hasMultipleAnswers = allAnswers.length > 1

                const answerShapes = allAnswers.map((a) => {
                    return a.transform(({ $ }) => ({
                        $id: $.val(NowIdShape.from(a)),
                        name: $.def(''),
                        answer: $.def(''),
                        type: $.map((v) => {
                            const raw = v.ifString()?.getValue() ?? ''
                            const mapped = ANSWER_CODE_TO_TYPE[raw]
                            if (raw && !mapped) {
                                logger.warn(
                                    `Unrecognized answer type code "${raw}" on sys_wizard_answer ${a.getId().getValue()} — leaving as-is.`
                                )
                            }
                            return mapped ?? (raw || undefined)
                        }).def(DEFAULT_ANSWER_TYPE),
                        targetUrl: $.from('target_url').def(''),
                        nextQuestion: $.from('next_question').map(
                            (v) => v.ifString()?.ifNotEmpty()?.getValue() ?? v.ifRecord()?.getId()?.getValue()
                        ),
                        buttonLabel: $.from('button_label').def(''),
                        table: $.def(''),
                        element: $.def(''),
                        dependentValue: $.from('dependent_value').def(''),
                        script: $.def(''),
                        roles: $.map((v) => splitList(v.ifString()?.getValue())).def([]),
                        // .toNumber() throws on an empty string, which order can be on legacy/malformed
                        // platform data (e.g. an answer created before this field had a default) —
                        // ifNotEmpty() guards that the same way nextQuestion/backPanel/etc. above do.
                        // hasMultipleAnswers must still always emit a real number (see comment above), so
                        // a blank value there is substituted with the platform default directly rather than
                        // through .def(), which only fills in a value when it's used to decide omission.
                        order: hasMultipleAnswers
                            ? $.map((v) => v.ifString()?.ifNotEmpty()?.toNumber().getValue() ?? DEFAULT_ORDER)
                            : $.map((v) => v.ifString()?.ifNotEmpty()?.toNumber().getValue()).def(DEFAULT_ORDER),
                        active: $.toBoolean().def(true),
                        payloadName: $.from('payload_name').def(''),
                    }))
                })

                return {
                    success: true,
                    value: new CallExpressionShape({
                        source: record,
                        callee: 'Interceptor',
                        args: [
                            record.transform(({ $ }) => ({
                                name: $,
                                question: $.def(''),
                                backPanel: $.from('back_panel').map(
                                    (v) => v.ifString()?.ifNotEmpty()?.getValue() ?? v.ifRecord()?.getId()?.getValue()
                                ),
                                nextPanel: $.from('next_panel').map(
                                    (v) => v.ifString()?.ifNotEmpty()?.getValue() ?? v.ifRecord()?.getId()?.getValue()
                                ),
                                intercepts: $.def(''),
                                protectionPolicy: $.from('sys_policy').def(''),
                                answers: $.val(answerShapes.length ? answerShapes : undefined),
                            })),
                        ],
                    }),
                }
            },
        },
    },

    shapes: [
        {
            shape: CallExpressionShape,
            fileTypes: ['fluent'],
            async toRecord(callExpression, { factory, diagnostics, config }) {
                if (callExpression.getCallee() !== 'Interceptor') {
                    return { success: false }
                }

                const arg = callExpression.getArgument(0).asObject()

                const wizardRecord = await factory.createRecord({
                    source: callExpression,
                    table: INTERCEPTOR_TABLE,
                    properties: arg.transform(({ $ }) => ({
                        name: $,
                        question: $.def(''),
                        back_panel: $.from('backPanel').map(toReferenceShape).def(''),
                        next_panel: $.from('nextPanel').map(toReferenceShape).def(''),
                        intercepts: $.def(''),
                        sys_policy: $.from('protectionPolicy'),
                    })),
                })

                const answerArgs = arg.get('answers')?.ifArray()?.getElements() ?? []
                const answerRecords = []
                const resolvedOrders: number[] = []

                for (const a of answerArgs) {
                    const answerObj = a.asObject()

                    validateServerScriptField(answerObj.get('script'), diagnostics, config.serverModulesDir)

                    const answerType = answerObj.get('type').ifString()?.getValue() ?? DEFAULT_ANSWER_TYPE
                    const typeCode = ANSWER_TYPE_TO_CODE[answerType as InterceptorAnswerType] ?? answerType

                    const answerText = answerObj.get('answer').ifString()?.ifNotEmpty()?.getValue() ?? ''
                    const answerName = answerObj.get('name').ifString()?.ifNotEmpty()?.getValue() ?? answerText

                    // No server-side validation exists on sys_wizard_answer — these are hints,
                    // not build-blocking errors.
                    if (answerType === 'answer' && !answerObj.get('targetUrl').ifString()?.ifNotEmpty()) {
                        diagnostics.hint(
                            answerObj,
                            "Answer type 'answer' typically sets 'targetUrl' — this answer has none and will not navigate anywhere when selected."
                        )
                    }
                    if (answerType === 'leadingQuestion' && !answerObj.get('nextQuestion').ifDefined()) {
                        diagnostics.hint(
                            answerObj,
                            "Answer type 'leadingQuestion' typically sets 'nextQuestion' — this answer has none and will not advance to another question."
                        )
                    }
                    if (answerType === 'button') {
                        if (!answerObj.get('buttonLabel').ifString()?.ifNotEmpty()) {
                            diagnostics.hint(
                                answerObj,
                                "Answer type 'button' typically sets 'buttonLabel' — this answer has none and will render an unlabeled button."
                            )
                        }
                        if (answerObj.get('answer').ifString()?.ifNotEmpty()) {
                            diagnostics.warn(
                                answerObj.get('answer'),
                                "The 'answer' field is stored but not displayed when type is 'button'; use 'buttonLabel' for the visible button text."
                            )
                        }
                    }
                    if (answerType === 'externalChoice') {
                        const hasTable = answerObj.get('table').ifString()?.ifNotEmpty()
                        const hasElement = answerObj.get('element').ifString()?.ifNotEmpty()
                        const hasDependentValue = answerObj.get('dependentValue').ifString()?.ifNotEmpty()
                        if (!hasTable && !hasElement) {
                            diagnostics.hint(
                                answerObj,
                                "Answer type 'externalChoice' typically sets 'table' (and 'element') — this answer has none and will not source any choices."
                            )
                        } else if (hasTable && !hasElement) {
                            diagnostics.hint(
                                answerObj,
                                "Answer type 'externalChoice' sets 'table' but is missing 'element'; the platform requires both to source dynamic choices."
                            )
                        } else if (!hasTable && hasElement) {
                            diagnostics.warn(
                                answerObj,
                                "Answer type 'externalChoice' sets 'element' but is missing 'table'; 'element' is ignored without 'table'."
                            )
                        }
                        if (hasDependentValue && !(hasTable && hasElement)) {
                            diagnostics.warn(
                                answerObj,
                                "Answer type 'externalChoice' sets 'dependentValue' but 'table'/'element' are missing or incomplete; 'dependentValue' is ignored without both."
                            )
                        }
                    }
                    if (answerType === 'yesNo' || answerType === 'freeformText') {
                        if (!answerObj.get('payloadName').ifString()?.ifNotEmpty()) {
                            diagnostics.hint(
                                answerObj,
                                `Answer type '${answerType}' captures user input via 'payloadName' at runtime; set 'payloadName' to a meaningful identifier so the collected value is accessible.`
                            )
                        }
                    }
                    if (answerType === 'multipleChoice') {
                        // sys_wizard_choice has no Fluent API (see the interceptor-guide topic) —
                        // this always fires, since there is no build-time way to tell whether the
                        // choices have already been added on a given target instance.
                        diagnostics.hint(
                            answerObj,
                            "Answer type 'multipleChoice' has no choices in Fluent — add sys_wizard_choice records manually on the instance after deploying."
                        )
                    }

                    resolvedOrders.push(answerObj.get('order').ifNumber()?.getValue() ?? DEFAULT_ORDER)

                    const answerRecord = await factory.createRecord({
                        source: callExpression,
                        table: INTERCEPTOR_ANSWER_TABLE,
                        explicitId: answerObj.get('$id'),
                        properties: answerObj.transform(({ $ }) => ({
                            question: $.val(wizardRecord.getId()),
                            name: $.val(answerName),
                            answer: $.def(''),
                            type: $.val(typeCode),
                            target_url: $.from('targetUrl').def(''),
                            next_question: $.from('nextQuestion').map(toReferenceShape).def(''),
                            button_label: $.from('buttonLabel').def(''),
                            table: $.from('table').def(''),
                            element: $.from('element').def(''),
                            dependent_value: $.from('dependentValue').def(''),
                            script: $.def('').toCdata(),
                            roles: $.map((v) =>
                                v
                                    .ifArray()
                                    ?.getElements()
                                    .map((el) => {
                                        if (el.isString()) {
                                            return el.asString().getValue()
                                        } else if (el.isObject()) {
                                            return el.get('name')?.ifString()?.getValue() ?? ''
                                        }
                                        return ''
                                    })
                                    .join(',')
                            ),
                            order: $.def(DEFAULT_ORDER),
                            active: $.def(true),
                            payload_name: $.from('payloadName').def(''),
                        })),
                    })

                    answerRecords.push(answerRecord)
                }

                // Warn when sibling answers resolve to the same order value — display
                // order on the instance becomes unpredictable when siblings tie. toShape above
                // always emits `order` (never omits it via .def()) once there are 2+ answers, so
                // this never fires against a value the developer can't see in their own file.
                //
                // One warning per tied order VALUE, not one per tied answer: a real base-system
                // wizard can have hundreds of answers left at the platform default (order 100),
                // which previously produced one near-identical warning per answer — e.g. 709
                // warnings for a single record — flooding build output without adding
                // information beyond the first. Grouping bounds the warning count by the number
                // of distinct tied order values (almost always 1) instead of the number of
                // answers sharing them.
                if (answerArgs.length > 1) {
                    const orderToAnswerIndexes = new Map<number, number[]>()
                    resolvedOrders.forEach((order, i) => {
                        const indexes = orderToAnswerIndexes.get(order) ?? []
                        indexes.push(i)
                        orderToAnswerIndexes.set(order, indexes)
                    })

                    for (const [order, indexes] of orderToAnswerIndexes) {
                        const firstIndex = indexes[0]
                        if (indexes.length <= 1 || firstIndex === undefined) {
                            continue
                        }
                        // Anchor on the first tied sibling so the warning still points at a real,
                        // editable location rather than the whole Interceptor call.
                        const firstAnswerArg = answerArgs[firstIndex]
                        if (!firstAnswerArg) {
                            continue
                        }
                        const first = firstAnswerArg.asObject()
                        diagnostics.warn(
                            first.get('order').ifDefined() ?? first,
                            `${indexes.length} answers share order ${order} — display order on the instance will be unpredictable. Set distinct order values for each sibling answer.`
                        )
                    }
                }

                return { success: true, value: wizardRecord.with(...answerRecords) }
            },
        },
    ],
})
